<?php
session_start();
require __DIR__ . '/../config.php';
require __DIR__ . '/_layout.php';
redirect_to_login();
$pdo=db();$msg='';$errorMsg='';
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$csrf=$_SESSION['csrf_token'];
$config=$pdo->query("SELECT * FROM build_config WHERE id=1")->fetch(PDO::FETCH_ASSOC);
if(!$config)$config=array('repo_owner'=>'teeqp13-ops','repo_name'=>'gpsq','workflow_file'=>'build.yml','branch'=>'main','github_token'=>null);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??''))$errorMsg='انتهت صلاحية الطلب، أعد تحميل الصفحة';
 else{
  $action=$_POST['action']??'';
  if($action==='save_config'){
   $owner=trim($_POST['repo_owner']??'');$repo=trim($_POST['repo_name']??'');$workflow=trim($_POST['workflow_file']??'build.yml');$branch=trim($_POST['branch']??'main');$tokenInput=trim($_POST['github_token']??'');$encrypted=$config['github_token'];if($tokenInput!==''&&$tokenInput!=='••••••••')$encrypted=wf_encrypt($tokenInput);$stmt=$pdo->prepare("UPDATE build_config SET repo_owner=?,repo_name=?,workflow_file=?,branch=?,github_token=?,updated_at=? WHERE id=1");$stmt->execute(array($owner,$repo,$workflow,$branch,$encrypted,date('Y-m-d H:i:s')));$config=$pdo->query("SELECT * FROM build_config WHERE id=1")->fetch(PDO::FETCH_ASSOC);$msg='تم حفظ إعدادات الربط';
  }elseif($action==='trigger_build'){
   $token=wf_decrypt($config['github_token']);if(!$token)$errorMsg='أضف توكن GitHub أولاً';else{$path='/repos/'.rawurlencode($config['repo_owner']).'/'.rawurlencode($config['repo_name']).'/actions/workflows/'.rawurlencode($config['workflow_file']).'/dispatches';$r=wf_github_request('POST',$path,$token,array('ref'=>$config['branch']));$msg=$r['ok']?'تم إرسال أمر البناء بنجاح':'';if(!$r['ok'])$errorMsg='فشل بدء البناء ('.$r['code'].')';}
  }elseif($action==='upload_repo_file'){
   $token=wf_decrypt($config['github_token']);$repoPath=trim(str_replace('\\','/',$_POST['repo_path']??''));$commit=trim($_POST['commit_message']??'تحديث السورس من لوحة WolFox');
   if(!$token)$errorMsg='أضف توكن GitHub أولاً';elseif(!isset($_FILES['repo_file'])||$_FILES['repo_file']['error']!==UPLOAD_ERR_OK)$errorMsg='اختر ملفاً صالحاً';elseif($repoPath===''||str_contains($repoPath,'..')||str_starts_with($repoPath,'/'))$errorMsg='مسار المستودع غير صالح';elseif($_FILES['repo_file']['size']>5*1024*1024)$errorMsg='الحد الأعلى 5MB';else{$content=file_get_contents($_FILES['repo_file']['tmp_name']);$api='/repos/'.rawurlencode($config['repo_owner']).'/'.rawurlencode($config['repo_name']).'/contents/'.str_replace('%2F','/',rawurlencode($repoPath));$existing=wf_github_request('GET',$api.'?ref='.rawurlencode($config['branch']),$token);$payload=array('message'=>$commit?:'تحديث السورس من لوحة WolFox','content'=>base64_encode($content),'branch'=>$config['branch']);if($existing['ok']&&!empty($existing['data']['sha']))$payload['sha']=$existing['data']['sha'];$r=wf_github_request('PUT',$api,$token,$payload);if($r['ok'])$msg='تم رفع الملف: '.$repoPath;else $errorMsg='فشل الرفع ('.$r['code'].')'.(!empty($r['data']['message'])?': '.$r['data']['message']:'');}
  }
 }
}
$notifications=wf_notifications($pdo);
?>
<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WolFox - GitHub والبناء</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"></head><body><?php wf_sidebar('build');?><main class="main-content"><?php wf_topbar('المستودع والبناء','ربط GitHub ورفع ملفات السورس وتشغيل البناء من اللوحة.',$notifications);?><?php if($msg):?><div class="alert-box alert-success"><i class="fas fa-circle-check"></i><?php echo htmlspecialchars($msg);?></div><?php endif;?><?php if($errorMsg):?><div class="alert-box alert-danger"><i class="fas fa-triangle-exclamation"></i><?php echo htmlspecialchars($errorMsg);?></div><?php endif;?><section class="panel"><div class="panel-title"><i class="fa-brands fa-github"></i> ربط المستودع</div><form method="POST" class="form-stack"><input type="hidden" name="action" value="save_config"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf);?>"><div class="settings-grid"><label>المالك<input class="input-control" name="repo_owner" value="<?php echo htmlspecialchars($config['repo_owner']);?>"></label><label>المستودع<input class="input-control" name="repo_name" value="<?php echo htmlspecialchars($config['repo_name']);?>"></label><label>الفرع<input class="input-control" name="branch" value="<?php echo htmlspecialchars($config['branch']);?>"></label><label>Workflow<input class="input-control" name="workflow_file" value="<?php echo htmlspecialchars($config['workflow_file']);?>"></label></div><label>GitHub Token<input class="input-control" type="password" name="github_token" placeholder="<?php echo $config['github_token']?'محفوظ — اتركه فارغاً':'github_pat_...';?>" autocomplete="off"></label><button class="btn btn-primary"><i class="fas fa-floppy-disk"></i> حفظ الربط</button></form></section><section class="panel"><div class="panel-title"><i class="fas fa-code-commit"></i> رفع ملف إلى المستودع</div><form method="POST" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="action" value="upload_repo_file"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf);?>"><label>الملف<input class="input-control file-control" type="file" name="repo_file" required></label><label>المسار داخل المستودع<input class="input-control" name="repo_path" placeholder="injector/WFActivationPanel.mm" required></label><label>رسالة Commit<input class="input-control" name="commit_message" value="تحديث السورس من لوحة WolFox"></label><button class="btn btn-primary"><i class="fa-brands fa-github"></i> رفع إلى GitHub</button></form></section><section class="panel"><div class="panel-title"><i class="fas fa-hammer"></i> تشغيل البناء</div><form method="POST"><input type="hidden" name="action" value="trigger_build"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf);?>"><button class="btn btn-primary"><i class="fas fa-play"></i> بدء البناء الآن</button></form></section></main><div id="toast" class="toast"></div><script src="app.js"></script></body></html>
